const st = window.__ensemble;
const s0 = st.getState();
window.__d = { chatId: s0.chatId, agents: [], tasks: [], states: {}, screens: {} };
const D = window.__d;
const missing = (s) => {
  const c = s.chats.find(c => c.id === D.chatId); if (!c) return false;
  if (D.agents.some(a => !s.members[a.id])) return true;
  if (!D.agents.every(a => (c.agents || []).some(x => x.id === a.id && !!x.spawned?.gone === !!a.spawned.gone))) return true;
  const cur = s.tasks[D.chatId] || [];
  if (!D.tasks.every(t => cur.some(x => x.id === t.id && x.status === t.status))) return true;
  for (const [k, v] of Object.entries(D.states)) { const x = s.agents[k]; if (!x || x.phase !== v.phase || x.activity !== v.activity) return true; }
  for (const [k, v] of Object.entries(D.screens)) { const x = s.screens[k]; if (x && x.active !== v.active) return true; }
  return false;
};
D.apply = () => st.setState(s => {
  const out = {};
  const ids = new Set(D.agents.map(a => a.id));
  out.chats = s.chats.map(c => c.id !== D.chatId ? c : { ...c, agents: [...(c.agents || []).filter(x => !ids.has(x.id) && !String(x.id).startsWith('fk-')), ...D.agents] });
  out.members = { ...s.members, ...Object.fromEntries(D.agents.map(a => [a.id, a])) };
  const tids = new Set(D.tasks.map(t => t.id));
  out.tasks = { ...s.tasks, [D.chatId]: [...(s.tasks[D.chatId] || []).filter(x => !tids.has(x.id) && !String(x.id).startsWith('fk-')), ...D.tasks] };
  const agents = { ...s.agents };
  for (const k of Object.keys(agents)) if (k.startsWith(D.chatId + ':fk-') && !D.states[k]) delete agents[k];
  out.agents = { ...agents, ...D.states };
  const screens = { ...s.screens };
  for (const [k, v] of Object.entries(D.screens)) if (screens[k]) screens[k] = { ...screens[k], ...v };
  out.screens = screens;
  return out;
});
st.subscribe(s => { if (missing(s)) setTimeout(D.apply, 0); });

