window.__fake = (n, opts = {}) => {
  const s = st.getState();
  const lead = (s.chats.find(c => c.id === D.chatId) || {}).leadId || s.settings.leadId || s.accounts.find(a => a.enabled).id;
  D.lead = lead;
  const pick = R.slice(0, n);
  const accents = ['teal', 'blue', 'violet', 'clay', 'green', 'amber', 'rose', 'slate'];
  const fid = id => 'fk-' + id;
  const gone = new Set(opts.gone || []);
  D.agents = pick.map(([id, name, by, model], i) => {
    const byId = by === 'lead' ? lead : fid(by);
    return { id: fid(id), name, provider: model.startsWith('gpt') ? 'chatgpt' : 'claude', accent: accents[i % accents.length], enabled: true, model, effort: null, role: name.replace(/ \S+$/, ''), spawned: { chatId: D.chatId, base: lead, by: byId, depth: by === 'lead' ? 1 : 2, at: now - (60 - i) * 1000, gone: gone.has(id) } };
  });
  D.tasks = pick.map(([id, name, by, model, label, effort, status, act, title], i) => ({
    id: 'fk-t-' + id, chatId: D.chatId, title, brief: title + '. Return what you found with sources.', from: by === 'lead' ? lead : fid(by), to: fid(id),
    status: status === 'waiting' ? 'running' : status, createdAt: now - 120000, startedAt: status === 'queued' ? undefined : now - (30 + i * 9) * 1000,
    finishedAt: status === 'done' || status === 'failed' ? now - 4000 * i : undefined, model, modelLabel: label, effort,
    after: status === 'queued' ? ['t1', 't2'] : undefined, waitingOn: status === 'queued' ? (name.startsWith('Judge') ? ['Builder A', 'Builder B'] : ['Scout 1', 'Scout 2']) : undefined,
  }));
  D.states = {};
  pick.forEach(([id, name, by, model, label, effort, status, act], i) => {
    const busy = status === 'running' || status === 'waiting';
    D.states[D.chatId + ':' + fid(id)] = { chatId: D.chatId, accountId: fid(id), phase: status === 'waiting' ? 'waiting' : busy ? (i % 2 ? 'tool' : 'thinking') : status === 'failed' ? 'error' : 'idle', activity: busy ? act : undefined, queued: 0, taskId: busy || status === 'queued' ? 'fk-t-' + id : null, model, turnStartedAt: busy ? now - (25 + i * 11) * 1000 : undefined, error: status === 'failed' ? 'The search tool timed out' : undefined };
  });
  // The lead is at work too.
  D.states[D.chatId + ':' + lead] = { chatId: D.chatId, accountId: lead, phase: 'thinking', activity: 'Waiting on ' + Math.max(1, pick.filter(r => r[6] === 'running').length) + ' agents', queued: 0, model: 'claude-fable-5-2', turnStartedAt: now - 184000 };
